[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CreativeHub — Online Classes for Creatives</title>
  <meta name="description" content="Join 425k+ creative professionals on CreativeHub. Thousands of online classes in illustration, design, photography, filmmaking, and more. Start your free 7-day trial.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400&display=swap" rel="stylesheet">
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.3.0/fonts/remixicon.css" rel="stylesheet">
  <style>
    /* ============================================================
       DESIGN SYSTEM
       ============================================================ */
    :root {
      --black:        #000000;
      --green:        #55DA9B;
      --purple:       #5620C1;
      --purple-mid:   #6B35D4;
      --purple-light: #8B52E8;
      --dark:         #080812;
      --dark-card:    #0F0F1E;
      --white:        #FFFFFF;
      --off-white:    #F7F6FD;
      --gray-100:     #F2F0FA;
      --gray-200:     #E4E1F5;
      --gray-400:     #9E9BB8;
      --gray-600:     #6B6880;
      --gray-800:     #2D2A45;
      --font: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
      --radius-sm:   8px;
      --radius-md:   12px;
      --radius-lg:   16px;
      --radius-xl:   24px;
      --radius-pill: 100px;
      --shadow-sm:   0 1px 3px rgba(0,0,0,0.07), 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md:   0 4px 14px rgba(0,0,0,0.09), 0 2px 6px rgba(0,0,0,0.06);
      --shadow-lg:   0 12px 36px rgba(0,0,0,0.13), 0 4px 14px rgba(0,0,0,0.08);
      --shadow-purple: 0 4px 20px rgba(86,32,193,0.28);
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

    body {
      font-family: var(--font);
      color: var(--black);
      background: var(--white);
      line-height: 1.6;
      overflow-x: hidden;
    }

    img { display: block; max-width: 100%; }
    a { text-decoration: none; }

    /* ============================================================
       UTILITIES
       ============================================================ */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

    .section-tag {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--purple);
      background: rgba(86,32,193,0.08);
      padding: 6px 14px;
      border-radius: var(--radius-pill);
      margin-bottom: 14px;
    }

    .section-header { text-align: center; margin-bottom: 40px; }

    .section-title {
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 800;
      letter-spacing: -0.025em;
      color: var(--black);
      line-height: 1.15;
    }

    .section-subtitle {
      font-size: 17px;
      color: var(--gray-600);
      margin-top: 10px;
      max-width: 560px;
      margin-left: auto;
      margin-right: auto;
      line-height: 1.7;
    }

    /* ============================================================
       BUTTONS
       ============================================================ */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      font-family: var(--font);
      font-weight: 600;
      font-size: 15px;
      border-radius: var(--radius-pill);
      border: none;
      cursor: pointer;
      transition: all 0.22s cubic-bezier(0.22,1,0.36,1);
      text-decoration: none;
      white-space: nowrap;
    }

    .btn-nav-signin {
      background: transparent;
      color: var(--gray-600);
      padding: 9px 18px;
    }
    .btn-nav-signin:hover { background: var(--gray-100); color: var(--black); }

    .btn-nav-signup {
      background: var(--purple);
      color: white;
      padding: 9px 22px;
      box-shadow: var(--shadow-purple);
    }
    .btn-nav-signup:hover { background: var(--purple-mid); transform: translateY(-1px); box-shadow: 0 6px 24px rgba(86,32,193,0.38); }

    .btn-google {
      background: white;
      color: var(--black);
      padding: 15px 30px;
      font-size: 16px;
      border: 2px solid rgba(255,255,255,0.2);
      box-shadow: 0 2px 12px rgba(0,0,0,0.25);
    }
    .btn-google:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(0,0,0,0.3); }

    .btn-email {
      background: rgba(255,255,255,0.1);
      color: white;
      padding: 15px 30px;
      font-size: 16px;
      border: 2px solid rgba(255,255,255,0.22);
    }
    .btn-email:hover { background: rgba(255,255,255,0.18); transform: translateY(-2px); border-color: rgba(255,255,255,0.4); }

    /* ============================================================
       NAVIGATION
       ============================================================ */
    .nav {
      position: sticky;
      top: 0;
      z-index: 200;
      background: rgba(255,255,255,0.94);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--gray-200);
    }

    .nav-inner {
      display: flex;
      align-items: center;
      gap: 8px;
      height: 68px;
    }

    .nav-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 19px;
      font-weight: 800;
      color: var(--black);
      text-decoration: none;
      flex-shrink: 0;
      margin-right: 16px;
    }

    .nav-logo-mark {
      width: 34px;
      height: 34px;
      background: var(--purple);
      border-radius: 9px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 17px;
    }

    .nav-link {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      text-decoration: none;
      padding: 8px 14px;
      border-radius: var(--radius-sm);
      transition: color 0.18s, background 0.18s;
    }
    .nav-link:hover { color: var(--black); background: var(--gray-100); }

    .nav-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }

    /* ============================================================
       HERO
       ============================================================ */
    .hero {
      background: var(--dark);
      padding: 88px 0 64px;
      position: relative;
      overflow: hidden;
    }

    .hero-glow {
      position: absolute;
      top: -280px;
      left: 50%;
      transform: translateX(-50%);
      width: 1100px;
      height: 700px;
      background: radial-gradient(ellipse at center, rgba(86,32,193,0.45) 0%, rgba(85,218,155,0.08) 50%, transparent 72%);
      pointer-events: none;
    }

    .hero-dots {
      position: absolute;
      inset: 0;
      background-image:
        radial-gradient(circle, rgba(255,255,255,0.04) 1px, transparent 1px);
      background-size: 32px 32px;
      pointer-events: none;
    }

    .hero-inner {
      position: relative;
      z-index: 1;
      text-align: center;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(85,218,155,0.1);
      border: 1px solid rgba(85,218,155,0.22);
      color: var(--green);
      font-size: 13px;
      font-weight: 600;
      padding: 7px 16px;
      border-radius: var(--radius-pill);
      margin-bottom: 28px;
    }

    .hero-title {
      font-size: clamp(38px, 6.5vw, 76px);
      font-weight: 800;
      line-height: 1.07;
      color: white;
      max-width: 820px;
      margin: 0 auto 18px;
      letter-spacing: -0.03em;
    }

    .hero-title .accent-green {
      background: linear-gradient(130deg, var(--green) 0%, #9BEDD0 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-subtitle {
      font-size: 20px;
      font-weight: 500;
      color: rgba(255,255,255,0.58);
      margin-bottom: 38px;
    }

    .hero-ctas {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 14px;
      margin-bottom: 18px;
      flex-wrap: wrap;
    }

    .hero-legal {
      font-size: 11.5px;
      color: rgba(255,255,255,0.3);
      max-width: 500px;
      margin: 0 auto 52px;
      line-height: 1.65;
    }
    .hero-legal a { color: rgba(255,255,255,0.48); text-decoration: underline; }

    .hero-categories-label {
      font-size: 11px;
      font-weight: 700;
      color: rgba(255,255,255,0.35);
      text-transform: uppercase;
      letter-spacing: 0.12em;
      margin-bottom: 14px;
    }

    .hero-pills {
      display: flex;
      gap: 10px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .hero-pill {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      color: rgba(255,255,255,0.72);
      font-size: 13.5px;
      font-weight: 500;
      padding: 8px 18px;
      border-radius: var(--radius-pill);
      cursor: pointer;
      transition: all 0.2s;
      white-space: nowrap;
    }
    .hero-pill:hover {
      background: rgba(85,218,155,0.12);
      border-color: rgba(85,218,155,0.35);
      color: var(--green);
    }

    /* ============================================================
       FEATURES
       ============================================================ */
    .features {
      padding: 88px 0;
      background: var(--off-white);
    }

    .features-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .features-title {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      line-height: 1.12;
      letter-spacing: -0.025em;
      margin-bottom: 36px;
    }

    .feature-item {
      display: flex;
      gap: 16px;
      margin-bottom: 26px;
    }
    .feature-item:last-child { margin-bottom: 0; }

    .feature-icon {
      width: 46px;
      height: 46px;
      border-radius: 13px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 21px;
      flex-shrink: 0;
    }
    .fi-1 { background: var(--purple); color: white; }
    .fi-2 { background: var(--green); color: #0A5C38; }
    .fi-3 { background: #F59E0B; color: white; }
    .fi-4 { background: #EF4444; color: white; }

    .feature-content h3 {
      font-size: 16px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 3px;
    }
    .feature-content p { font-size: 14.5px; color: var(--gray-600); line-height: 1.55; }

    .features-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }

    .fv-hero-card {
      grid-column: 1 / -1;
      background: linear-gradient(135deg, var(--purple) 0%, #8B4CF8 100%);
      border-radius: var(--radius-xl);
      padding: 26px;
      display: flex;
      align-items: center;
      gap: 18px;
      color: white;
    }

    .fv-hero-icon {
      width: 58px;
      height: 58px;
      background: rgba(255,255,255,0.18);
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 27px;
      flex-shrink: 0;
    }

    .fv-hero-card h4 { font-size: 18px; font-weight: 700; margin-bottom: 4px; }
    .fv-hero-card p { font-size: 14px; opacity: 0.75; }

    .fv-stat-card {
      background: white;
      border-radius: var(--radius-lg);
      padding: 22px;
      border: 1px solid var(--gray-200);
      box-shadow: var(--shadow-sm);
      text-align: center;
    }

    .fv-num {
      font-size: 34px;
      font-weight: 800;
      color: var(--purple);
      line-height: 1;
      margin-bottom: 6px;
      letter-spacing: -0.02em;
    }
    .fv-lbl { font-size: 13px; color: var(--gray-600); font-weight: 500; }

    /* ============================================================
       STATS
       ============================================================ */
    .stats-band {
      background: var(--dark);
      padding: 72px 0;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0;
    }

    .stat-item {
      text-align: center;
      padding: 20px 24px;
      border-right: 1px solid rgba(255,255,255,0.07);
    }
    .stat-item:last-child { border-right: none; }

    .stat-value {
      font-size: clamp(38px, 5vw, 58px);
      font-weight: 800;
      color: var(--green);
      line-height: 1;
      margin-bottom: 10px;
      letter-spacing: -0.03em;
    }

    .stat-label {
      font-size: 15px;
      color: rgba(255,255,255,0.48);
      font-weight: 500;
    }

    /* ============================================================
       COURSES
       ============================================================ */
    .courses { padding: 88px 0; background: white; }

    .course-tabs-wrap {
      position: relative;
      margin-bottom: 32px;
    }

    .course-tabs {
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding: 2px 0 6px;
      scrollbar-width: none;
    }
    .course-tabs::-webkit-scrollbar { display: none; }

    .tab-btn {
      flex-shrink: 0;
      font-family: var(--font);
      font-size: 13.5px;
      font-weight: 600;
      padding: 8px 18px;
      border-radius: var(--radius-pill);
      border: 2px solid var(--gray-200);
      background: white;
      color: var(--gray-600);
      cursor: pointer;
      transition: all 0.2s;
      white-space: nowrap;
    }
    .tab-btn:hover { border-color: var(--purple); color: var(--purple); background: rgba(86,32,193,0.04); }
    .tab-btn.active { background: var(--purple); color: white; border-color: var(--purple); box-shadow: var(--shadow-purple); }

    .course-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .course-card {
      background: white;
      border-radius: var(--radius-lg);
      border: 1px solid var(--gray-200);
      overflow: hidden;
      cursor: pointer;
      transition: all 0.26s cubic-bezier(0.22,1,0.36,1);
    }
    .course-card:hover { transform: translateY(-5px); box-shadow: var(--shadow-lg); border-color: transparent; }

    .course-thumb {
      aspect-ratio: 16/9;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .course-thumb-bg {
      position: absolute;
      inset: 0;
    }

    .course-thumb-icon {
      font-size: 44px;
      color: rgba(255,255,255,0.55);
      position: relative;
      z-index: 1;
      transition: transform 0.2s;
    }
    .course-card:hover .course-thumb-icon { transform: scale(1.15); }

    .play-overlay {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      background: rgba(0,0,0,0.22);
      opacity: 0;
      transition: opacity 0.2s;
      z-index: 2;
    }
    .course-card:hover .play-overlay { opacity: 1; }

    .play-circle {
      width: 44px;
      height: 44px;
      background: white;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--purple);
      font-size: 18px;
    }

    .course-info { padding: 14px 16px 16px; }

    .course-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--black);
      line-height: 1.45;
      margin-bottom: 7px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .course-instructor { font-size: 12.5px; color: var(--gray-600); margin-bottom: 10px; }

    .course-meta {
      display: flex;
      align-items: center;
      gap: 14px;
      font-size: 12px;
      color: var(--gray-400);
      font-weight: 600;
    }
    .course-meta span { display: flex; align-items: center; gap: 4px; }
    .course-meta i { font-size: 13px; }

    /* No courses message */
    .courses-empty {
      grid-column: 1 / -1;
      text-align: center;
      padding: 60px 24px;
      color: var(--gray-400);
    }
    .courses-empty i { font-size: 48px; margin-bottom: 12px; display: block; }
    .courses-empty p { font-size: 16px; font-weight: 500; }

    /* ============================================================
       CREATIVE FEED
       ============================================================ */
    .creative-feed { padding: 88px 0; background: var(--off-white); }

    .feed-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 22px;
      margin-top: 40px;
    }

    .feed-card {
      background: white;
      border-radius: var(--radius-xl);
      padding: 34px 28px;
      border: 1px solid var(--gray-200);
      transition: all 0.26s cubic-bezier(0.22,1,0.36,1);
    }
    .feed-card:hover { transform: translateY(-5px); box-shadow: var(--shadow-lg); }

    .feed-icon-wrap {
      width: 58px;
      height: 58px;
      border-radius: 15px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 25px;
      margin-bottom: 22px;
    }
    .fi-green { background: rgba(85,218,155,0.14); color: #1A9466; }
    .fi-purple { background: rgba(86,32,193,0.1); color: var(--purple); }
    .fi-amber { background: rgba(245,158,11,0.12); color: #C97D0A; }

    .feed-card h3 { font-size: 20px; font-weight: 700; color: var(--black); margin-bottom: 10px; }
    .feed-card p { font-size: 15px; color: var(--gray-600); line-height: 1.72; }

    /* ============================================================
       TEACHERS
       ============================================================ */
    .teachers { padding: 88px 0; background: white; }

    .carousel-outer { position: relative; margin-top: 40px; }

    .carousel-track {
      display: flex;
      gap: 18px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      padding: 4px 2px 8px;
    }
    .carousel-track::-webkit-scrollbar { display: none; }

    .teacher-card {
      flex-shrink: 0;
      width: 210px;
      scroll-snap-align: start;
      background: white;
      border-radius: var(--radius-xl);
      border: 1px solid var(--gray-200);
      padding: 26px 20px 22px;
      text-align: center;
      cursor: pointer;
      transition: all 0.26s cubic-bezier(0.22,1,0.36,1);
    }
    .teacher-card:hover { transform: translateY(-5px); box-shadow: var(--shadow-lg); border-color: transparent; }

    .teacher-avatar {
      width: 80px;
      height: 80px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      font-weight: 800;
      color: white;
      margin: 0 auto 16px;
      border: 3px solid rgba(255,255,255,0.4);
    }

    .teacher-name { font-size: 15.5px; font-weight: 700; color: var(--black); margin-bottom: 5px; }
    .teacher-spec { font-size: 13px; color: var(--gray-600); line-height: 1.45; margin-bottom: 16px; }

    .follow-btn {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      font-size: 12.5px;
      font-weight: 700;
      color: var(--purple);
      background: rgba(86,32,193,0.08);
      padding: 7px 15px;
      border-radius: var(--radius-pill);
      border: none;
      cursor: pointer;
      transition: all 0.2s;
      font-family: var(--font);
    }
    .follow-btn:hover { background: var(--purple); color: white; }

    .carousel-nav {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-top: 22px;
    }

    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid var(--gray-200);
      background: white;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      color: var(--gray-600);
      transition: all 0.2s;
    }
    .carousel-btn:hover { border-color: var(--purple); color: var(--purple); background: rgba(86,32,193,0.05); }

    .carousel-dots {
      display: flex;
      gap: 6px;
      flex: 1;
    }

    .carousel-dot {
      width: 6px;
      height: 6px;
      border-radius: 3px;
      background: var(--gray-200);
      cursor: pointer;
      transition: all 0.2s;
    }
    .carousel-dot.active { width: 20px; background: var(--purple); }

    /* ============================================================
       TESTIMONIALS
       ============================================================ */
    .testimonials { padding: 88px 0; background: var(--off-white); }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 20px;
      margin-top: 40px;
    }

    .testimonial-card {
      background: white;
      border-radius: var(--radius-xl);
      padding: 30px;
      border: 1px solid var(--gray-200);
      position: relative;
      transition: all 0.26s;
    }
    .testimonial-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }

    .t-quote {
      font-family: Georgia, 'Times New Roman', serif;
      font-size: 52px;
      line-height: 0.8;
      color: var(--green);
      margin-bottom: 14px;
      display: block;
    }

    .t-text {
      font-size: 15.5px;
      color: var(--gray-800);
      line-height: 1.72;
      margin-bottom: 22px;
      font-style: italic;
    }

    .t-author { display: flex; align-items: center; gap: 12px; }

    .t-avatar {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 15px;
      font-weight: 800;
      color: white;
      flex-shrink: 0;
    }

    .t-name { font-size: 14.5px; font-weight: 700; color: var(--black); }

    .t-stars { display: flex; gap: 2px; margin-top: 3px; }
    .t-stars i { font-size: 12px; color: #F59E0B; }

    /* ============================================================
       TEAMS
       ============================================================ */
    .teams {
      padding: 88px 0;
      background: var(--purple);
      position: relative;
      overflow: hidden;
    }

    .teams-glow {
      position: absolute;
      top: -150px; right: -200px;
      width: 700px; height: 700px;
      background: radial-gradient(circle, rgba(255,255,255,0.07) 0%, transparent 65%);
      pointer-events: none;
    }

    .teams-glow-2 {
      position: absolute;
      bottom: -200px; left: -100px;
      width: 500px; height: 500px;
      background: radial-gradient(circle, rgba(85,218,155,0.12) 0%, transparent 65%);
      pointer-events: none;
    }

    .teams-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 70px;
      align-items: center;
      position: relative;
      z-index: 1;
    }

    .teams-text h2 {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      color: white;
      line-height: 1.12;
      letter-spacing: -0.025em;
      margin-bottom: 18px;
    }

    .teams-text p {
      font-size: 16px;
      color: rgba(255,255,255,0.72);
      line-height: 1.8;
      margin-bottom: 30px;
    }

    .btn-teams-cta {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      background: white;
      color: var(--purple);
      padding: 15px 30px;
      font-size: 16px;
      font-weight: 700;
      border-radius: var(--radius-pill);
      border: none;
      cursor: pointer;
      transition: all 0.22s;
      font-family: var(--font);
      text-decoration: none;
    }
    .btn-teams-cta:hover { transform: translateY(-2px); box-shadow: 0 10px 30px rgba(0,0,0,0.22); }

    .teams-cards {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }

    .teams-card {
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.14);
      border-radius: var(--radius-lg);
      padding: 24px;
      text-align: center;
    }

    .teams-card-val {
      font-size: 38px;
      font-weight: 800;
      color: var(--green);
      line-height: 1;
      margin-bottom: 7px;
      letter-spacing: -0.02em;
    }

    .teams-card-lbl { font-size: 13.5px; color: rgba(255,255,255,0.62); font-weight: 500; }

    /* ============================================================
       FAQ
       ============================================================ */
    .faq { padding: 88px 0; background: white; }

    .faq-list { max-width: 760px; margin: 40px auto 0; }

    .faq-item { border-bottom: 1px solid var(--gray-200); }
    .faq-item:first-child { border-top: 1px solid var(--gray-200); }

    .faq-q {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 22px 0;
      cursor: pointer;
      font-size: 16.5px;
      font-weight: 700;
      color: var(--black);
      transition: color 0.18s;
      user-select: none;
      list-style: none;
      background: none;
      border: none;
      width: 100%;
      text-align: left;
      font-family: var(--font);
    }
    .faq-q:hover { color: var(--purple); }
    .faq-q.open { color: var(--purple); }

    .faq-icon {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 17px;
      color: var(--gray-600);
      flex-shrink: 0;
      transition: all 0.25s;
    }
    .faq-q.open .faq-icon {
      background: rgba(86,32,193,0.1);
      color: var(--purple);
      transform: rotate(45deg);
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.32s ease;
    }

    .faq-answer-inner {
      padding: 0 0 22px;
      font-size: 15.5px;
      color: var(--gray-600);
      line-height: 1.78;
    }

    /* ============================================================
       FOOTER
       ============================================================ */
    .footer { background: var(--dark); padding: 72px 0 36px; }

    .footer-top {
      display: grid;
      grid-template-columns: 240px 1fr;
      gap: 60px;
      padding-bottom: 52px;
      margin-bottom: 52px;
      border-bottom: 1px solid rgba(255,255,255,0.07);
    }

    .footer-brand-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 18px;
      font-weight: 800;
      color: white;
      margin-bottom: 14px;
    }

    .footer-brand-logo-mark {
      width: 32px;
      height: 32px;
      background: var(--purple);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 15px;
    }

    .footer-tagline {
      font-size: 14px;
      color: rgba(255,255,255,0.38);
      line-height: 1.7;
      margin-bottom: 22px;
    }

    .footer-social {
      display: flex;
      gap: 10px;
    }

    .social-btn {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      color: rgba(255,255,255,0.5);
      font-size: 16px;
      cursor: pointer;
      transition: all 0.2s;
      text-decoration: none;
    }
    .social-btn:hover { background: rgba(255,255,255,0.12); color: white; }

    .footer-nav-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 28px;
    }

    .footer-col h4 {
      font-size: 11.5px;
      font-weight: 700;
      color: rgba(255,255,255,0.42);
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 16px;
    }

    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-col a { font-size: 13.5px; color: rgba(255,255,255,0.5); transition: color 0.18s; }
    .footer-col a:hover { color: white; }

    .footer-bottom {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .footer-bottom-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
    }

    .footer-copy { font-size: 13px; color: rgba(255,255,255,0.28); }

    .footer-legal { font-size: 12px; color: rgba(255,255,255,0.22); line-height: 1.65; }

    /* ============================================================
       MODAL
       ============================================================ */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(8,8,18,0.76);
      backdrop-filter: blur(6px);
      -webkit-backdrop-filter: blur(6px);
      z-index: 999;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.28s;
    }
    .modal-overlay.open { opacity: 1; pointer-events: all; }

    .modal-box {
      background: white;
      border-radius: var(--radius-xl);
      padding: 42px 40px 36px;
      width: 100%;
      max-width: 436px;
      position: relative;
      transform: scale(0.94) translateY(16px);
      transition: transform 0.3s cubic-bezier(0.22,1,0.36,1);
    }
    .modal-overlay.open .modal-box { transform: scale(1) translateY(0); }

    .modal-close-btn {
      position: absolute;
      top: 14px; right: 14px;
      width: 36px; height: 36px;
      border-radius: 50%;
      background: var(--gray-100);
      border: none;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      color: var(--gray-600);
      transition: all 0.18s;
    }
    .modal-close-btn:hover { background: var(--gray-200); }

    .modal-logo {
      display: flex;
      align-items: center;
      gap: 9px;
      font-size: 16px;
      font-weight: 800;
      color: var(--black);
      margin-bottom: 22px;
    }

    .modal-logo-mark {
      width: 28px; height: 28px;
      background: var(--purple);
      border-radius: 7px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 14px;
    }

    .modal-h { font-size: 24px; font-weight: 800; color: var(--black); letter-spacing: -0.02em; margin-bottom: 6px; }
    .modal-sub { font-size: 14.5px; color: var(--gray-600); margin-bottom: 28px; }
    .modal-sub strong { color: var(--green); font-weight: 700; }

    .modal-google-btn {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      padding: 14px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-pill);
      background: white;
      font-family: var(--font);
      font-size: 15px;
      font-weight: 600;
      color: var(--black);
      cursor: pointer;
      transition: all 0.2s;
      margin-bottom: 14px;
    }
    .modal-google-btn:hover { border-color: var(--gray-400); box-shadow: var(--shadow-md); }

    .google-logo {
      width: 20px;
      height: 20px;
      flex-shrink: 0;
    }

    .modal-divider {
      display: flex;
      align-items: center;
      gap: 12px;
      margin: 18px 0;
      font-size: 12.5px;
      font-weight: 600;
      color: var(--gray-400);
    }
    .modal-divider::before, .modal-divider::after {
      content: '';
      flex: 1;
      height: 1px;
      background: var(--gray-200);
    }

    .modal-input {
      width: 100%;
      padding: 14px 20px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-pill);
      font-family: var(--font);
      font-size: 15px;
      color: var(--black);
      outline: none;
      transition: border-color 0.2s;
      margin-bottom: 12px;
    }
    .modal-input:focus { border-color: var(--purple); }
    .modal-input::placeholder { color: var(--gray-400); }

    .modal-submit-btn {
      width: 100%;
      padding: 14px;
      background: var(--purple);
      color: white;
      border: none;
      border-radius: var(--radius-pill);
      font-family: var(--font);
      font-size: 15px;
      font-weight: 700;
      cursor: pointer;
      transition: all 0.22s;
    }
    .modal-submit-btn:hover { background: var(--purple-mid); transform: translateY(-1px); box-shadow: 0 6px 20px rgba(86,32,193,0.38); }

    .modal-legal-text {
      font-size: 11.5px;
      color: var(--gray-400);
      text-align: center;
      margin-top: 16px;
      line-height: 1.65;
    }
    .modal-legal-text a { color: var(--gray-600); text-decoration: underline; }

    /* ============================================================
       RESPONSIVE
       ============================================================ */
    @media (max-width: 1024px) {
      .course-grid { grid-template-columns: repeat(3, 1fr); }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .stat-item { border-right: none; border-bottom: 1px solid rgba(255,255,255,0.07); }
      .stat-item:last-child { border-bottom: none; }
      .footer-nav-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 860px) {
      .features-grid { grid-template-columns: 1fr; gap: 40px; }
      .features-visual { display: none; }
      .teams-inner { grid-template-columns: 1fr; gap: 36px; }
      .teams-cards { display: none; }
    }

    @media (max-width: 768px) {
      .nav-link { display: none; }
      .hero { padding: 64px 0 48px; }
      .course-grid { grid-template-columns: repeat(2, 1fr); }
      .feed-grid { grid-template-columns: 1fr; }
      .testimonials-grid { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: 1fr; gap: 36px; }
      .footer-nav-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 520px) {
      .course-grid { grid-template-columns: 1fr; }
      .hero-ctas { flex-direction: column; }
      .btn-google, .btn-email { width: 100%; justify-content: center; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-nav-grid { grid-template-columns: 1fr 1fr; }
    }
  </style>
</head>
